const importDynamic = new Function('modulePath', 'return import(modulePath)');
async function req() {
	const gradio = await importDynamic('@gradio/client');
	const app = await client("eswardivi/Phi-3-mini-4k-instruct");
	const result = await app.predict("/chat", [		
		"Hello!!", // string  in 'Message' Textbox component		
		0.7, // number (numeric value between 0 and 1) in 'Temperature' Slider component		
		true, // boolean  in 'Sampling' Checkbox component		
		128, // number (numeric value between 128 and 4096) in 'Max new tokens' Slider component
	]);
	console.log(result);
	dbm.storeValue(result.data, 1, "result", cache);
	dbm.callNextAction(cache);
}
req();
```

